import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])

    if n == 1:
        print(1)
        print(1)
        return

    # We need to find primes up to n + 1
    limit = n + 1
    is_prime = [True] * (limit + 1)
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False

    colors = []
    for i in range(1, n + 1):
        price = i + 1
        if is_prime[price]:
            colors.append(2)
        else:
            colors.append(1)

    print(2)
    print(*(colors))

if __name__ == "__main__":
    main()
